        print("Quitting...")
        keyboard.terminate()
    else:
        print(f"Key pressed: {key.char}")

def on_key_release(key):
    print(f"Key released: {key.char}")

def on_key_press_event(event):
    print(f"Key pressed: {event.key_code}")

def on_key_release_event(event):
    print(f"Key released: {event.key_code}")

